export default function pages({ previous, messages, nextPageToken }) {
  const s = previous ?? { ids: [], tokens: [], awaiting: false };
  if (s.awaiting) {
    if (!Array.isArray(messages)) throw Error("Missing Gmail page");
    for (const m of messages) {
      if (!m || typeof m.messageId !== "string") throw Error("Invalid Gmail message");
      s.ids.push({ id: m.messageId });
    }
    if (nextPageToken) {
      if (s.tokens.includes(nextPageToken)) throw Error("Gmail pagination repeated");
      s.tokens.push(nextPageToken);
      s.token = nextPageToken;
    } else {
      s.done = true;
    }
  }
  if (s.done) return { state: s, more: false, token: "", records: s.ids };
  s.awaiting = true;
  return { state: s, more: true, token: s.token ?? "", records: s.ids };
}

