export default function events({ events }) {
  if (!Array.isArray(events)) throw Error("Invalid Gmail events");
  return {
    records: events.map((x) => {
      if (!x || typeof x.messageId !== "string") throw Error("Invalid Gmail event");
      return { id: x.messageId };
    }),
  };
}

